def _add_mode(main, extra, primary_id, primary_label, extra_id, extra_label):
    """Only combines explicitly written paths; it never writes scene or choice prose."""
    for a, b in zip(main['slots'], extra['slots']):
        for v in a['variants']:
            v['modes'] = [primary_id]
        for v in b['variants']:
            suffix = v['id'].rsplit('.', 1)[1]
            v['id'] = a['id'] + '.' + extra_id.upper() + '.' + suffix
            v['modes'] = [extra_id]
            a['variants'].append(v)
    main['modes'] = [
        {'id': primary_id, 'label': primary_label, 'initial_variants': {}},
        {'id': extra_id, 'label': extra_label,
         'initial_variants': {s['id']: s['id'] + '.' + extra_id.upper() + '.V1' for s in main['slots']}},
    ]


